const h = String((msg.req.headers || {}).authorization || '');
const dev = String((msg.req.query || {}).device || '');
msg.params = [h.replace(/^Bearer\s+/i, '').trim(), dev];
return msg;

const t = ((msg.payload && msg.payload[0]) || {}).token;
// Sem token = sessao invalida OU o usuario nao e dono do aparelho. Os dois
// casos respondem igual: distinguir revelaria quais device_id existem.
if (!t) { msg.statusCode = 404; msg.payload = { error: 'not_found' }; return msg; }
msg.statusCode = 200;
msg.payload = { token: t };
return msg;
